  async function performClose(target: ViewInfo) { try { await call('close', { viewId: target.id, retainRecovery: true }); setTabOrder(order => order.filter(id => id !== target.id)); if (activeId === target.id) setActiveId(undefined); setClosing(undefined); await refresh(); } catch(e) { alert(e); } }
  async function closeTab(target: ViewInfo) { await editQueue.current.catch(() => {}); const d = stateRef.current.documents.find(item => item.id === target.documentId); if(d?.dirty) setClosing(target); else await performClose(target); }
  async function saveAndClose() { if(!closing)return;setClosingBusy(true);try{await editQueue.current; const doc=stateRef.current.documents.find(d=>d.id===closing.documentId)!;if(desktop){if(!await call('choose-save',{documentId:doc.id}))return;}else{if(!doc.path)throw new Error('请先另存文档。');await call('save',{documentId:doc.id});}await performClose(closing);}catch(e){alert(e);}finally{setClosingBusy(false);} }
  async function navigate(direction: 'back' | 'forward') { if (document?.format === 'web' && desktop) { await call('browser-navigate', { viewId: view!.id, action: direction }); return; } const source = direction === 'back' ? history : future, dest = direction === 'back' ? future : history; const id = source.current.pop(); const next = workspace.views.find(v => v.id === id); if (next) { if (view) dest.current.push(view.id); await activate(next, false); } }
